package com.drogaria.backend.service;
import com.drogaria.backend.dto.*; import com.drogaria.backend.entity.Funcionario; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.FuncionarioRepository; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.util.List;
@Service public class FuncionarioService { private final FuncionarioRepository r; private final BCryptPasswordEncoder encoder; public FuncionarioService(FuncionarioRepository r,BCryptPasswordEncoder e){this.r=r;encoder=e;} public List<FuncionarioResponse> listar(){return r.findAll().stream().map(FuncionarioResponse::new).toList();} public FuncionarioResponse buscar(Integer id){return new FuncionarioResponse(r.findById(id).orElseThrow(()->new ApiException("Funcionario nao encontrado",HttpStatus.NOT_FOUND)));} public FuncionarioResponse salvar(FuncionarioRequest x){Funcionario f=new Funcionario();f.setNome(x.getNome());f.setEmail(x.getEmail().toLowerCase());f.setSenha(encoder.encode(x.getSenha()));return new FuncionarioResponse(r.save(f));} public FuncionarioResponse atualizar(Integer id,FuncionarioRequest x){Funcionario f=r.findById(id).orElseThrow(()->new ApiException("Funcionario nao encontrado",HttpStatus.NOT_FOUND));f.setNome(x.getNome());f.setEmail(x.getEmail().toLowerCase());if(x.getSenha()!=null&&!x.getSenha().isBlank())f.setSenha(encoder.encode(x.getSenha()));return new FuncionarioResponse(r.save(f));} public void excluir(Integer id){if(!r.existsById(id))throw new ApiException("Funcionario nao encontrado",HttpStatus.NOT_FOUND);r.deleteById(id);} }